INSERT INTO `categories` VALUES (1,'Camera','camera','Caméras de cinéma, appareils photo hybrides et reflex professionnels.',NULL,'fas fa-camera','images/camera/cat_cameras.jpg','active',1,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(2,'Objectifs','objectifs','Objectifs cinématographiques, focales fixes et zooms haute précision.',NULL,'fas fa-circle-notch','images/camera/hero_lens_optics.jpg','active',2,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(3,'Lumières / Matériel de studio','lumieres-materiel-de-studio','Panneaux LED, projecteurs COB, softboxes et accessoires d\'éclairage studio.',NULL,'fas fa-lightbulb','images/camera/cat_lighting.jpg','active',3,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(4,'Son','son','Micros HF sans fil, micros canon, enregistreurs audio et casques studio.',NULL,'fas fa-microphone','images/camera/cat_audio.jpg','active',4,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(5,'Stabilisateurs','stabilisateurs','Gimbals 3 axes motorisés, rigs et systèmes de stabilisation professionnels.',NULL,'fas fa-hand-holding','images/camera/cat_gimbals.jpg','active',5,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(6,'Sacs de caméra','sacs-de-camera','Sacs à dos photo, valises étanches antichoc et étuis de protection matériel.',NULL,'fas fa-briefcase','images/camera/cat_cameras.jpg','active',6,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(7,'Trépieds','trepieds','Trépieds vidéo professionnels, monopodes et têtes fluides haute capacité.',NULL,'fas fa-grip-lines-vertical','images/camera/hero_cinema_rig.jpg','active',7,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(8,'Batterie / Chargeur','batterie-chargeur','Batteries V-Mount, batteries d\'origine, chargeurs rapides et adaptateurs secteur.',NULL,'fas fa-battery-three-quarters','images/camera/cat_cameras.jpg','active',8,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(9,'Carte mémoire / Lecteur','carte-memoire-lecteur','Cartes CFexpress, SD V90/V60 ultra-rapides, disques SSD et lecteurs USB-C.',NULL,'fas fa-sd-card','images/camera/cat_cameras.jpg','active',9,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(10,'Accessoires','accessoires','Câbles HDMI blindés, cages rig, poignées, bras magiques et fixations.',NULL,'fas fa-tools','images/camera/cat_cameras.jpg','active',10,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(11,'Matériel de Podcast','materiel-de-podcast','Tables de mixage broadcast, bras articulés, micros dynamiques et interfaces podcast.',NULL,'fas fa-podcast','images/camera/cat_audio.jpg','active',11,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(12,'Filtres ND / CPL polarisé','filtres-nd-cpl-polarise','Filtres neutres variables ND, filtres polarisants circulaires CPL et filtres Black Mist.',NULL,'fas fa-adjust','images/camera/hero_lens_optics.jpg','active',12,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(13,'Matte Box','matte-box','Matte box légères en fibre de carbone, volets coupe-flux et porte-filtres cinéma.',NULL,'fas fa-video','images/camera/hero_cinema_rig.jpg','active',13,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(14,'Accessoires Insta360','accessoires-insta360','Perches invisibles, caissons étanches, batteries et supports pour caméras 360.',NULL,'fas fa-globe','images/camera/cat_drones.jpg','active',14,'2026-10-22 14:43:12','2026-10-22 14:43:12'),(15,'Kit de nettoyage','kit-de-nettoyage','Soufflettes d\'air, stylos optiques, microfibres de précision et kits capteur.',NULL,'fas fa-spray-can','images/camera/cat_cameras.jpg','active',15,'2026-10-22 14:43:12','2026-10-22 14:43:12');
